add_filter( 'the_content', 'perfectpixel_table_of_contents', 20 );

function perfectpixel_table_of_contents( $content ) {
	$types = array_filter( array_map( 'trim', explode( ',', '{{toc_post_types}}' ) ) );
	if ( ! is_singular( $types ) || ! in_the_loop() || ! is_main_query() ) {
		return $content;
	}
	if ( ! preg_match_all( '/<h([23])(\s[^>]*)?>(.*?)<\/h\1>/is', $content, $matches, PREG_SET_ORDER ) || count( $matches ) < max( 1, (int) '{{toc_min_headings}}' ) ) {
		return $content;
	}

	$used  = array();
	$items = '';
	foreach ( $matches as $i => $m ) {
		$attrs = isset( $m[2] ) ? $m[2] : '';
		$text  = trim( wp_strip_all_tags( $m[3] ) );
		if ( '' === $text ) {
			continue;
		}
		if ( preg_match( '/\sid=["\']([^"\']+)["\']/i', $attrs, $id_match ) ) {
			$id      = $id_match[1];
			$heading = $m[0];
		} else {
			$id = sanitize_title( $text );
			// Non-Latin titles become percent-encoded slugs; use a simple numbered id instead.
			if ( '' === $id || false !== strpos( $id, '%' ) ) {
				$id = 'toc-' . ( $i + 1 );
			}
			$base = $id;
			$n    = 2;
			while ( isset( $used[ $id ] ) ) {
				$id = $base . '-' . $n++;
			}
			$heading = '<h' . $m[1] . $attrs . ' id="' . esc_attr( $id ) . '">' . $m[3] . '</h' . $m[1] . '>';
			$content = preg_replace( '/' . preg_quote( $m[0], '/' ) . '/', $heading, $content, 1 );
		}
		$used[ $id ] = true;
		$items      .= '<li' . ( '3' === $m[1] ? ' style="margin-left:1.25em"' : '' ) . '><a href="#' . esc_attr( $id ) . '">' . esc_html( $text ) . '</a></li>';
	}
	if ( '' === $items ) {
		return $content;
	}

	$toc = '<details class="perfectpixel-toc" open style="border:1px solid rgba(0,0,0,.12);border-radius:4px;padding:.75em 1em;margin:0 0 1.5em"><summary style="cursor:pointer;font-weight:600">' . esc_html( '{{toc_title}}' ) . '</summary><ul style="list-style:none;margin:.5em 0 0;padding:0">' . $items . '</ul></details>';
	$pos = stripos( $content, '<h' . $matches[0][1] );
	return false === $pos ? $toc . $content : substr_replace( $content, $toc, $pos, 0 );
}
